input.new_string:
// ElectrocardiogramData type for csx-mobile-upgrade project
export interface ElectrocardiogramData {
  heartRate: number;
  rriMax: number;
  rriMin: number;
  hrv: number;
  mood: string;
  respiratoryRate: number;
  waveData: number[];
  paperSpeed: number;
  gain: number;
  userName?: string;
  birthDate?: string;
  recordTime:string;//"2025-08-27T06:03:18.954Z"
}

/** Runtime guard: interfaces have no JS value, so use shape checks (aligned with ECGPDFGenerator waveData validation). */
export function isElectrocardiogramData(value: unknown): value is ElectrocardiogramData {
  if (value == null || typeof value !== 'object') {
    return false;
  }
  const o = value as Partial<ElectrocardiogramData>;
  return (
    Array.isArray(o.waveData) &&
    o.waveData.length > 0 &&
    typeof o.recordTime === 'string'
  );
}

